function deferred<T>(){let resolve!:(v:T)=>void,reject!:(v:unknown)=>void;const promise=new Promise<T>((a,b)=>{resolve=a;reject=b;});void promise.catch(()=>{});return {promise,resolve,reject};}
async function until(predicate:()=>boolean){for(let i=0;i<1000&&!predicate();i++)await new Promise<void>(resolve=>actualTimer(resolve,1));expect(predicate()).toBe(true);}
type Method='Page.getFrameTree'|'Target.getTargetInfo'|'Tracing.start'|'Tracing.end'|'IO.read'|'IO.close';
type Params={categories:string;transferMode:'ReturnAsStream';streamFormat:'json';streamCompression:'none'}|{handle:string;size:65536}|{handle:string};
class Protocol implements ComparisonTraceProtocolBoundary {
 readonly calls:{method:Method;params:Params|undefined}[]=[];
 readonly listeners=new Map<string,(payload:unknown)=>void>();
 readonly events:{operation:'on'|'off';event:string;listener:(payload:unknown)=>void}[]=[];
 frames:unknown=frame;targets:unknown=target;completion:unknown={stream:'actual-handle',dataLossOccurred:false,traceFormat:'json',streamCompression:'none'};
 chunks:unknown[]=[{data:'hé\n',eof:false},{data:'AP8E',base64Encoded:true,eof:false},{data:'',eof:true}];
 handler:((method:Method,params:Params|undefined)=>Promise<unknown>)|undefined;detachHandler:(()=>Promise<void>)|undefined;offHandler:((event:string)=>void)|undefined;onHandler:((event:string)=>void)|undefined;
 send(method:'Page.getFrameTree'|'Target.getTargetInfo'|'Tracing.end'):Promise<unknown>;
 send(method:'Tracing.start',params:{categories:string;transferMode:'ReturnAsStream';streamFormat:'json';streamCompression:'none'}):Promise<unknown>;
 send(method:'IO.read',params:{handle:string;size:65536}):Promise<unknown>;
 send(method:'IO.close',params:{handle:string}):Promise<unknown>;
 async send(method:Method,params?:Params):Promise<unknown>{
  this.calls.push({method,params});if(this.handler)return this.handler(method,params);return this.normal(method,params);
 }
 normal(method:Method,params:Params|undefined):unknown {
  if(method==='IO.read'){expect(params).toEqual({handle:'actual-handle',size:65536});return this.chunks.shift()??{data:'',eof:true};}
  if(method==='IO.close'){expect(params&&'handle' in params).toBe(true);return {};}
  if(method==='Tracing.start'){expect(params).toEqual({categories:PRESENTATION_TRACE_CATEGORIES.join(','),transferMode:'ReturnAsStream',streamFormat:'json',streamCompression:'none'});return {};}
  expect(params).toBeUndefined();if(method==='Page.getFrameTree')return this.frames;if(method==='Target.getTargetInfo')return this.targets;if(method==='Tracing.end')this.emit('Tracing.tracingComplete',this.completion);return {};
 }
 on(event:'Tracing.bufferUsage'|'Tracing.tracingComplete',listener:(payload:unknown)=>void):unknown;
 on(event:'close',listener:()=>void):unknown;
 on(event:string,listener:(payload:unknown)=>void){this.events.push({operation:'on',event,listener});this.listeners.set(event,listener);this.onHandler?.(event);}
 off(event:'Tracing.bufferUsage'|'Tracing.tracingComplete',listener:(payload:unknown)=>void):unknown;
 off(event:'close',listener:()=>void):unknown;
 off(event:string,listener:(payload:unknown)=>void){this.events.push({operation:'off',event,listener});expect(this.listeners.get(event)).toBe(listener);this.listeners.delete(event);this.offHandler?.(event);}
 emit(event:string,payload:unknown){this.listeners.get(event)?.(payload);}
 async detach(){if(this.detachHandler)await this.detachHandler();this.emit('close',undefined);}
}
type Fixture={capture:ComparisonTraceCapture;protocol:Protocol;owner:ComparisonOwnership;context:ComparisonSlotContext;writer:ComparisonArtifactWriter;directory:string;adopted:()=>number;release:(fn:()=>void)=>void;restore:(fn:()=>void)=>void;beginDisposal:()=>ReturnType<ComparisonOwnership['dispose']>;deferCleanup:()=>()=>void};
async function withTrace(body:(f:Fixture)=>Promise<void>,options:{protocol?:Protocol;io?:ComparisonFileOperations;isolation?:boolean;single?:boolean;decorateOwnership?:(ctx:ComparisonOwnershipContext)=>ComparisonOwnershipContext;expectedStage?:'complete'|'expired'}={}) {
 const preparation=mkdtemp(join(tmpdir(),'comparison-trace-'));void preparation.catch(()=>{});const directory=await preparation,owner=new ComparisonOwnership({now:Date.now}),releases:(()=>void)[]=[],restorations:(()=>void)[]=[];
 let capture:ComparisonTraceCapture|undefined,failed=false,error:unknown,adopted=0,actualBody:Promise<void>|undefined,firstDisposal:ReturnType<ComparisonOwnership['dispose']>|undefined;
 let observation:Promise<void>|undefined,observed:(()=>void)|undefined,stageResult:Awaited<ReturnType<ComparisonOwnership['run']>>|undefined;
 const deferCleanup=()=>{if(observation)throw Error('Only one cleanup observation per fixture');observation=new Promise<void>(resolve=>{observed=resolve;});return ()=>observed?.();};
 const record=(e:unknown)=>{if(!failed){failed=true;error=e;}};
 const beginDisposal=()=>{firstDisposal??=owner.dispose();void firstDisposal.catch(()=>{});return firstDisposal;};
 try {
  const writer=await ComparisonArtifactWriter.create(directory,options.io);await writer.scoped(()=>{}).text('trace.json','');const protocol=options.protocol??new Protocol();
  const stage=owner.run('replay',async actualOwnership=>{
   try {
   const ownership=options.decorateOwnership?.(actualOwnership)??actualOwnership;
   const scoped=writer.scoped(()=>ownership.assertActive());
   const context:ComparisonSlotContext={identity,descriptor:comparisonScheduledRunSchema.parse({...identity,seed:1,mode:'headless',artifactDirectory:'runs/one'}),fixture:createLongThreadFixture({seed:1,historyCount:100,responseBytes:6400,journey:'follow'}),ownership,writer:{...scoped,async stream(path){const raw=await scoped.stream(path);adopted++;await ownership.adopt({name:`artifact-stream:${path}`,close:()=>raw.complete()});return raw;}}};
   capture=createComparisonTraceCaptureForProtocolFixture({context,protocol,isolatedBrowserProcess:options.isolation??true,singleWorkloadPage:options.single??true,now:Date.now});
   const task=body({capture,protocol,owner,context,writer,directory,adopted:()=>adopted,release:fn=>releases.push(fn),restore:fn=>restorations.push(fn),beginDisposal,deferCleanup});actualBody=task;void task.catch(record);
   await task;
   }catch(e){record(e);}finally{observed?.();}
  });
  void stage.catch(record);stageResult=await stage;
  // Tests that inspect unsafe held state explicitly finish that observation;
  // ordinary expiry never waits for body work before automatic cleanup.
  if(stageResult.status==='expired'&&observation)await observation;
 }catch(e){record(e);}
 finally {
  // Cleanup starts before release/waits, including the owner's independent raw lane.
  const cleanup=capture?.close();void cleanup?.catch(()=>{});const disposal=beginDisposal();
  for(const release of releases)release();await Promise.allSettled([cleanup,disposal,actualBody]);await owner.ownershipSettled;for(const restore of restorations)restore();await rm(directory,{recursive:true,force:true});
 }
 if(failed)throw error;expect(stageResult?.status).toBe(options.expectedStage??'complete');return owner;
}

