it('trace fixture expiry starts cleanup and registered release before awaiting held body',async()=>{const hold=deferred<unknown>(),protocol=new Protocol();let held=false,released=false,bodySettled=false;protocol.detachHandler=async()=>{await new Promise<void>(resolve=>actualTimer(resolve,75));};protocol.handler=async(method,params)=>{if(method==='IO.read'){held=true;return hold.promise;}return protocol.normal(method,params);};const task=withTrace(async({capture,release})=>{release(()=>{released=true;hold.resolve({data:'',eof:true});});await capture.start();await expect(capture.finish()).rejects.toThrow();bodySettled=true;},{protocol,expectedStage:'expired'});void task.catch(()=>{});try{await until(()=>held);await vi.advanceTimersByTimeAsync(30000);await until(()=>released&&bodySettled);await task;expect(released).toBe(true);expect(bodySettled).toBe(true);}finally{hold.resolve({data:'',eof:true});await task;}});
it('healthy trace reaches complete after actual EOF IO close and first raw complete',async()=>{
 const expected=Buffer.concat([Buffer.from('hé\n'),Buffer.from([0,255,4])]);
 const owner=await withTrace(async({capture,protocol,directory,adopted,context,restore})=>{
  const original=context.writer.stream;
  const stream=vi.spyOn(context.writer,'stream').mockImplementation(async path=>{const raw=await original(path),complete=raw.complete;const persistence=vi.spyOn(raw,'complete').mockImplementation(()=>{expect(capture.snapshot().traceEof.status).toBe('available');return complete();});restore(()=>persistence.mockRestore());return raw;});restore(()=>stream.mockRestore());
  protocol.handler=async(method,params)=>{if(method==='IO.close')expect(capture.snapshot().traceEof.status).toBe('available');return protocol.normal(method,params);};
  await capture.start();await capture.finish();const snapshot=capture.snapshot();const close=capture.close();expect(capture.close()).toBe(close);await close;
  expect(adopted()).toBe(1);expect(snapshot.trace.status==='available'&&snapshot.trace.complete).toBe(true);expect(snapshot.auxiliary.status).toBe('complete');expect(snapshot.traceEof.status).toBe('available');expect(snapshot.payload.status).toBe('complete');
  const bytes=await readFile(join(directory,'trace.json'));expect(bytes).toEqual(expected);expect(createHash('sha256').update(bytes).digest('hex')).toBe(createHash('sha256').update(expected).digest('hex'));
  expect(comparisonTraceSchema.safeParse(snapshot.trace).success).toBe(true);expect(comparisonTraceAuxiliarySchema.safeParse(snapshot.auxiliary).success).toBe(true);
  expect(protocol.calls.find(c=>c.method==='Tracing.start')?.params).toEqual({categories:PRESENTATION_TRACE_CATEGORIES.join(','),transferMode:'ReturnAsStream',streamFormat:'json',streamCompression:'none'});
  expect(protocol.calls.filter(c=>c.method==='IO.read').map(c=>c.params)).toEqual(Array.from({length:3},()=>({handle:'actual-handle',size:65536})));
 });
 expect(owner.failures).toEqual([]);expect(owner.canContinue).toBe(true);
});

