function fixtureObjects(root:unknown):Set<object>{const set=new Set<object>();function visit(v:unknown){if(v===null||typeof v!=='object'||set.has(v))return;set.add(v);for(const key of Object.keys(v)){const d=Object.getOwnPropertyDescriptor(v,key);if(d&&'value' in d)visit(d.value);}}visit(root);return set;}
async function topology(value:unknown,accepted:boolean,maxDescriptors:number=70000){const protocol=new Protocol();protocol.frames=value;const identities=fixtureObjects(value);await withTrace(async({capture,restore})=>{let reads=0;const realDescriptor=Object.getOwnPropertyDescriptor;const descriptor=vi.spyOn(Object,'getOwnPropertyDescriptor').mockImplementation((object,key)=>{if(identities.has(object))reads++;return realDescriptor(object,key);});const parser=vi.spyOn(presentationEvidenceSchema,'parse');const clone=vi.spyOn(globalThis,'structuredClone');restore(()=>descriptor.mockRestore());restore(()=>parser.mockRestore());restore(()=>clone.mockRestore());await capture.start();expect(parser).toHaveBeenCalledTimes(accepted?1:0);expect(clone).not.toHaveBeenCalled();expect(reads).toBeLessThanOrEqual(maxDescriptors);const snapshot=capture.snapshot();expect(snapshot.trace.status==='available'&&snapshot.trace.presentation.status==='available').toBe(accepted);const before=reads;capture.snapshot();expect(reads).toBe(before);await capture.finish();},{protocol});}
